// Direct sum of all periodic pair images without neighbor lists or shared force code.
#include <algorithm>
#include <cmath>
#include <vector>
const int N=32, dofs=96;
const double a=.9975140800337228, bx=4*a, by=2*a*std::sqrt(3.0);
void read(const double *x,double *f,int power) {
    std::fill(f,f+dofs,0.);
    for(int u=0;u<N;u++) for(int v=0;v<u;v++) {
        double dx=std::remainder(x[3*u]-x[3*v],bx),dy=std::remainder(x[3*u+1]-x[3*v+1],by);
        double h=x[3*u+2]-x[3*v+2], s=std::min(1.,std::abs(h));
        double S=s*s*s*(10.+s*(-15.+6.*s)), dS=30.*s*s*(1.-s)*(1.-s)*std::copysign(1.,h);
        double w=power==1?S:S*S, dw=power==1?dS:2.*S*dS;
        for(int i=-1;i<=1;i++) for(int j=-1;j<=1;j++) {
            double xx=dx+i*bx, yy=dy+j*by, r2=xx*xx+yy*yy+h*h;
            if(r2>=20.25) continue;
            double r=std::sqrt(r2), v0=std::exp(7.*(1.-r)), v1=std::exp(10.*(.94-r));
            double g=(14.*v0*(1.-v0)*(1.-w)+12.*v1*(1.-v1)*w)/r;
            double t[3]={g*xx,g*yy,g*h+dw*(.6*v1*(v1-2.)-v0*(v0-2.))};
            for(int k=0;k<3;k++) {f[3*v+k]+=t[k];f[3*u+k]-=t[k];}
        }
    }
}
extern "C" void path(double *x, const double *w,const double *chi,int n,double dt,int p,int held) {
    double f[dofs];
    const double sitepull=3.9696964417191336*(bx*by/16.);
    for(int t=0;t<n;t++) {
        read(x,f,p);
        double shift[2]={0.,0.};
        for(int u=0;u<N;u++){
            double sign=(u<16?-1.:1.);
            f[3*u+2]+=chi[t]*(sign*sitepull-98.*(x[3*u+2]-.5*sign));
            for(int k=0;k<3;k++) {
                double delta=dt*f[3*u+k]+w[t*dofs+3*u+k];
                x[3*u+k]+=delta;
                if(k==0) shift[u/16]+=delta/16.;
            }
        }
        if(held) for(int u=0;u<N;u++) x[3*u]-=shift[u/16];
    }
}
extern "C" double traction(double *x,int p,int direction) {
    double f[dofs],sum=0.;
    read(x,f,p);
    for(int u=16;u<N;u++) sum-=f[3*u+direction];
    return sum/(bx*by);
}

