#include <algorithm>
#include <cmath>
const int N=32;
const double pitch=.9975140800337228;
double calc(const double *pos,double *force,int power,double g){
    double lx=4*pitch*std::exp(g),ly=2*std::sqrt(3.)*pitch*std::exp(-g),sum=0.;
    std::fill(force,force+96,0.);
    for(int i=0;i<N;i++) for(int j=0;j<=i;j++){
        double xx=std::remainder(pos[3*i]-pos[3*j],lx), yy=std::remainder(pos[3*i+1]-pos[3*j+1],ly);
        double z=pos[3*i+2]-pos[3*j+2],t=std::min(std::abs(z),1.);
        double f=t*t*t*(10.-15.*t+6*t*t),df=std::copysign(30.*t*t*(1.-t)*(1.-t),z);
        if(power==2){df*=2*f;f*=f;}
        for(int u=-1;u<=1;u++) for(int v=-1;v<=1;v++){
            if(i==j && (u<0 || (u==0 && v<=0))) continue;
            double x=xx+u*lx,y=yy+v*ly,r2=x*x+y*y+z*z;
            if(r2>=20.25) continue;
            double r=std::sqrt(r2),a=std::exp(7.*(1.-r)),b=std::exp(10.*(.94-r));
            double radial=((1.-f)*14.*a*(1.-a)+f*12.*b*(1.-b))/r;
            sum+=radial*(x*x-y*y);
            if(i!=j) {
                double ff[]={radial*x,radial*y,radial*z+df*(.6*b*(b-2.)-a*(a-2.))};
                for(int k=0;k<3;k++) {force[3*i+k]-=ff[k];force[3*j+k]+=ff[k];}
            }
        }
    }
    return sum/(lx*ly);
}
extern "C" double sigma(const double *x,int power,double g){
    double f[96];return calc(x,f,power,g);
}
extern "C" void step(double *x,const double *dw,int steps,double dt,int power,double g){
    double f[96];
    for(int t=0;t<steps;t++){
        calc(x,f,power,g);
        for(int k=0;k<96;k++) x[k]+=dt*f[k]+dw[96*t+k];
    }
}

